import{_ as t,o as s,c as e,a2 as o}from"./chunks/framework.CqGPl1zp.js";const i="/newx-doc/assets/Moonshot-%E5%AE%98%E6%96%B9.Dag701Pq.png",m=JSON.parse('{"title":"【模型接入】月之暗面","description":"","frontmatter":{},"headers":[],"relativePath":"ai/moonshot.md","filePath":"ai/moonshot.md","lastUpdated":null}'),n={name:"ai/moonshot.md"};function h(d,a,r,l,p,k){return s(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="【模型接入】月之暗面" tabindex="-1">【模型接入】月之暗面 <a class="header-anchor" href="#【模型接入】月之暗面" aria-label="Permalink to &quot;【模型接入】月之暗面&quot;">​</a></h1><p>项目基于 Spring AI + 自己实现的 <code>models/moonshot</code>，实现 <a href="https://www.moonshot.cn/" target="_blank" rel="noreferrer">Moonshot</a> 的接入，底层复用兼容 OpenAI 协议的客户端：</p><table tabindex="0"><thead><tr><th>功能</th><th>模型</th><th>Spring AI 客户端</th></tr></thead><tbody><tr><td>AI 对话</td><td>kimi-k2.7-code、kimi-k2.6 等</td><td>MoonshotChatModel</td></tr><tr><td>AI 绘画</td><td>不支持</td><td>暂未接入</td></tr></tbody></table><h2 id="_1-申请密钥" tabindex="-1">1. 申请密钥 <a class="header-anchor" href="#_1-申请密钥" aria-label="Permalink to &quot;1. 申请密钥&quot;">​</a></h2><p>Moonshot 有开源模型，可以私有化部署。</p><p>不过官方 API 服务使用也比较方便，可以去官网申请 API Key，然后通过项目接入。</p><h3 id="_1-1-方式一-申请-moonshot-密钥" tabindex="-1">1.1 方式一：申请 Moonshot 密钥 <a class="header-anchor" href="#_1-1-方式一-申请-moonshot-密钥" aria-label="Permalink to &quot;1.1 方式一：申请 Moonshot 密钥&quot;">​</a></h3><p>① 在 <a href="https://www.moonshot.cn/" target="_blank" rel="noreferrer">Moonshot</a> 上，注册一个账号。</p><p>② 在 <a href="https://platform.moonshot.cn/console/api-keys" target="_blank" rel="noreferrer">Moonshot 开放平台 -&gt; API Key 管理</a> 上，创建一个 API Key 密钥。</p><hr><p>申请完成后，可以在我们系统的 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单，进行密钥的配置。只需要填写“密钥”，不需要填写“自定义 API URL”（因为 Spring AI 默认官方地址）。如下图所示：</p><p><img src="'+i+`" alt="官方的密钥配置"></p><h2 id="_2-模型配置" tabindex="-1">2. 模型配置 <a class="header-anchor" href="#_2-模型配置" aria-label="Permalink to &quot;2. 模型配置&quot;">​</a></h2><p>友情提示：</p><p>目前 <code>ai_model</code> 表中，已经预置了一些模型，可以直接使用！！！</p><h3 id="_2-1-ai-对话" tabindex="-1">2.1 AI 对话 <a class="header-anchor" href="#_2-1-ai-对话" aria-label="Permalink to &quot;2.1 AI 对话&quot;">​</a></h3><p>使用 <a href="./chat">《AI 对话》</a> 时，需要在 [AI 大模型 -&gt; 控制台 -&gt; 模型配置] 菜单，配置对应的聊天模型，并选择前面配置的 Moonshot API 密钥。</p><p>不同模型的 <code>max_tokens</code>（回复数 Token 数）上限不同，可以参考下表填写：</p><table tabindex="0"><thead><tr><th>模型标识</th><th><code>max_tokens</code> 最大输出 Tokens</th></tr></thead><tbody><tr><td><code>kimi-k2.7-code</code></td><td>16384</td></tr><tr><td><code>kimi-k2.6</code></td><td>262144</td></tr></tbody></table><h3 id="_2-2-ai-绘图" tabindex="-1">2.2 AI 绘图 <a class="header-anchor" href="#_2-2-ai-绘图" aria-label="Permalink to &quot;2.2 AI 绘图&quot;">​</a></h3><p>TODO 等待 Moonshot ImageModel 客户端！</p><h2 id="_3-如何使用" tabindex="-1">3. 如何使用？ <a class="header-anchor" href="#_3-如何使用" aria-label="Permalink to &quot;3. 如何使用？&quot;">​</a></h2><p>① 如果你的项目里需要直接通过 <code>@Resource</code> 注入 MoonshotChatModel 等对象，需要把 <code>application.yaml</code> 配置文件里的 <code>yudao.ai.moonshot</code> 配置项，替换成你的！</p><div class="language-YAML vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">yudao</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    moonshot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 月之暗面（KIMI）</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      enable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      api-key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${MOONSHOT_API_KEY}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">kimi-k2.6</span></span></code></pre></div><p>② 如果你希望使用 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单的密钥配置，则可以通过 AiModelService 的 <code>#getChatModel(...)</code> 方法，获取对应的模型对象。</p><hr><p>① 和 ② 这两者的后续使用，就是标准的 Spring AI 客户端的使用，调用对应的方法即可。</p><p>另外，MoonshotChatModelTests 里有对应的测试用例，可以参考。</p>`,28)])])}const _=t(n,[["render",h]]);export{m as __pageData,_ as default};
